mapper.select:
SELECT detail.work_date, SUM(CASE WHEN detail.hours > 0 OR sheet.status = 'APPROVED' THEN detail.hours ELSE 0 END) AS hours
FROM oa_timesheet_detail detail JOIN oa_timesheet sheet ON sheet.timesheet_id = detail.timesheet_id AND sheet.tenant_id = detail.tenant_id
WHERE detail.tenant_id = #{tenantId} AND sheet.employee_id = #{employeeId} AND detail.deleted = 0 AND sheet.deleted = 0
  AND sheet.status IN ('DRAFT', 'SUBMITTED', 'APPROVING', 'APPROVED') AND detail.work_date BETWEEN #{from} AND #{to}
AND sheet.timesheet_id != #{excludeId}
GROUP BY detail.work_date

SELECT DISTINCT detail.timesheet_id FROM oa_timesheet_detail detail
JOIN oa_project project ON project.project_id = detail.project_id AND project.tenant_id = detail.tenant_id
WHERE detail.tenant_id = #{tenantId} AND detail.deleted = 0 AND project.deleted = 0 AND project.owner_id = #{userId}
